-- A forma de conferência (contagem manual / pesagem) passa do TAV para o Check-list da Contagem: atualiza o modelo ODT padrão do TAV, só se ainda for o padrão anterior.
update modelos set arquivo = decode('', 'base64'), atualizado_em = now()
where chave in ('tav', 'tav_padrao') and md5(arquivo) = '2c3e2822fa1c192f0e14f905589bd3d3';
